export interface MatchResultFields {
  resultType?: string | null;
}

export interface MatchProgressFields extends MatchResultFields {
  status: string;
  isVoided?: boolean;
}

/** A BYE is generated by the draw, not contested; it never counts as a real match. */
export function isRealMatch(match: MatchResultFields): boolean {
  return match.resultType !== 'BYE';
}

/** Contested, confirmed and not voided: the only matches that feed statistics and group tables. */
export function isPlayedMatch(match: MatchProgressFields): boolean {
  return match.status === 'OFFICIAL' && isRealMatch(match) && !match.isVoided;
}

/** A started real match freezes the draw structure. */
export function locksDrawStructure(match: MatchProgressFields): boolean {
  return (match.status === 'LIVE' || match.status === 'OFFICIAL') && isRealMatch(match);
}
